  assert.equal(retired.diagnostics.filter((item) => item.code === "VEL5055").length, 1);
  assert.match(retired.diagnostics.find((item) => item.code === "VEL5055")?.message ?? "", /const doubled = computed\(\(\) => \.\.\.\)/u);
