let closeReasonReads = 0;
socketValue.listeners.get("close")({
  get code() { closeCodeReads += 1; return closeCodeReads === 1 ? 1000 : 70000; },
  get reason() { closeReasonReads += 1; return closeReasonReads === 1 ? "done" : 0; },
});
